const studies={
scalp:{title:'ScalpGawd',label:'Trading software / engineering case study',context:'A Python trading-bot project. The engineering story is the design of a complex software system, rather than a claim of trading performance.',problem:'Market data, strategy rules, risk constraints, and order handling have distinct responsibilities. Coupling them makes changes and failures difficult to reason about.',architecture:'Proposed boundary map: data adapter → normalized market events → strategy module → risk gate → execution adapter. This is an architecture proposal for review against the repository, not a verified description of the current implementation.',testing:'Verification plan: deterministic strategy fixtures, boundary tests for risk limits, replay of historical events, and simulated execution failures. No backtest returns, live results, or passed tests are asserted here.',next:'Review the code, document implemented interfaces, and publish reproducible tests before adding performance claims.'},
whale:{title:'Whale Tracker',label:'Blockchain monitoring / engineering case study',context:'A transaction-monitoring project focused on turning blockchain activity into information that can be inspected.',problem:'Incoming transactions need consistent representation. Duplicate events, delayed data, and ambiguous thresholds can make monitoring unreliable.',architecture:'Proposed boundary map: provider adapter → transaction normalization → deduplication → threshold rules → presentation. Network coverage, providers, storage, and alert delivery remain unverified.',testing:'Verification plan: duplicate transactions, missing fields, late events, and threshold boundaries using synthetic fixtures. The portfolio illustration is conceptual and does not display live blockchain data.',next:'Confirm the implemented data pipeline and document what the tracker observes before publishing an interactive demo.'},
baymax:{title:'BAYMAX',label:'Desktop AI / engineering case study',context:'A desktop AI experimentation project. Its portfolio focus is the software boundary between interpreting a request and performing an action.',problem:'Natural-language input is uncertain, while desktop actions have concrete effects. A maintainable system needs explicit action contracts and understandable failure handling.',architecture:'Proposed boundary map: input → intent interpretation → validated command → action handler → feedback. Voice support, model choice, permissions, and implemented integrations require repository verification.',testing:'Verification plan: unknown intents, malformed parameters, cancelled actions, and handler failures. No desktop access or actual AI processing takes place on this portfolio page.',next:'Audit implemented commands, separate reversible actions from consequential ones, and capture a reproducible prototype walkthrough.'},
ops:{title:'OPS automation',label:'Excel / VBA / engineering case study',context:'Excel/VBA automation associated with the Ontario Public Service Student Services Assistant role in Summer 2025, as described in the prior portfolio discussion.',problem:'Repetitive administrative work creates opportunities to replace manual steps with a clearer, repeatable workflow.',architecture:'Review framework: identify inputs, validate required fields, isolate transformation logic, and provide output that a staff member can inspect. Exact workbook structure and automation scope are not independently verified.',testing:'Verification plan: compare representative manual and automated outputs, test blank and invalid inputs, and review recovery from interrupted processing. No time savings, adoption counts, or production test results are claimed.',next:'Confirm the workflow details and publish only a sanitized example that contains no government or personal records.'}
};
const caseDialog=document.querySelector('#case-dialog');
for(const button of document.querySelectorAll('.case-open'))button.addEventListener('click',()=>{const s=studies[button.dataset.case];document.querySelector('#case-content').innerHTML=`<p class="eyebrow">${s.label}</p><h2 id="case-title">${s.title}</h2><p>${s.context}</p><p class="caption">PROJECT CONTEXT REPORTED · IMPLEMENTATION DETAILS PENDING REVIEW</p><h3>The engineering problem</h3><p>${s.problem}</p><h3>Architecture to evaluate</h3><p>${s.architecture}</p><h3>Testing & evidence</h3><p>${s.testing}</p><h3>Next milestone</h3><p>${s.next}</p>`;caseDialog.showModal()});
const resumeDialog=document.querySelector('#resume-dialog');document.querySelectorAll('.resume-open').forEach(b=>b.addEventListener('click',()=>resumeDialog.showModal()));
document.querySelectorAll('dialog').forEach(d=>{d.querySelector('.close').addEventListener('click',()=>d.close());d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}})});
const reduced=matchMedia('(prefers-reduced-motion: reduce)');const motion=document.querySelector('#motion');let paused=reduced.matches;function updateMotion(){document.body.classList.toggle('paused',paused);motion.textContent=paused?'Resume motion':'Pause motion';motion.setAttribute('aria-pressed',String(paused))}updateMotion();motion.addEventListener('click',()=>{paused=!paused;updateMotion()});reduced.addEventListener('change',e=>{paused=e.matches;updateMotion()});
document.querySelectorAll('.tilt').forEach(card=>{card.addEventListener('pointermove',e=>{if(paused||reduced.matches||e.pointerType!=='mouse')return;const r=card.getBoundingClientRect();const x=(e.clientX-r.left)/r.width-.5,y=(e.clientY-r.top)/r.height-.5;card.style.transform=`perspective(1000px) rotateX(${-y*5}deg) rotateY(${x*7}deg) translateY(-3px)`});card.addEventListener('pointerleave',()=>card.style.transform='')});
